column8:
set -euo pipefail
case "${{ matrix.leg }}" in
  msvc-asan)    dir=build-asan-msvc;    extra=(-DROCKETNET_SANITIZE_ADDRESS=ON) ;;
  clangcl-asan) dir=build-asan-clangcl; extra=(-T ClangCL -DROCKETNET_SANITIZE_ADDRESS=ON -DCMAKE_MSVC_RUNTIME_LIBRARY=MultiThreadedDLL) ;;
  appverif)     dir=build-appverif;     extra=() ;;
  *) echo "unknown leg ${{ matrix.leg }}"; exit 1 ;;
esac
echo "LEG_BUILD_DIR=$dir" >> "$GITHUB_ENV"
echo "LEG_BIN=$dir/bin/Debug" >> "$GITHUB_ENV"
# each leg writes its binaries under its own build directory, so no leg replaces another's (or bin/)
cmake -B "$dir" -A x64 "${extra[@]}" "-DCMAKE_RUNTIME_OUTPUT_DIRECTORY=$PWD/$dir/bin" "-DCMAKE_LIBRARY_OUTPUT_DIRECTORY=$PWD/$dir/bin"
set -euo pipefail
cmake --build "$LEG_BUILD_DIR" --config Debug --parallel 4

